<?php
require_once __DIR__.'/config.php';require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='backup'){$out='-- HR Records backup generated '.date('c')."\nSET FOREIGN_KEY_CHECKS=0;\n";foreach(['users','employees','audit_logs'] as $table){$res=$db->query("SELECT * FROM `$table`");$out.="DELETE FROM `$table`;\n";while($row=$res->fetch_assoc()){$cols=array_map(fn($c)=>'`'.$c.'`',array_keys($row));$vals=array_map(fn($v)=>$v===null?'NULL':"'".$db->real_escape_string((string)$v)."'",array_values($row));$out.='INSERT INTO `'.$table.'` ('.implode(',',$cols).') VALUES ('.implode(',',$vals).");\n";}}$out.="SET FOREIGN_KEY_CHECKS=1;\n";audit($db,'DATABASE_BACKUP_CREATED','database',null,'SQL backup downloaded');header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="hr_records_backup_'.date('Ymd_His').'.sql"');echo $out;exit;}}
page_header('Database backup');echo '<h1>Database backup</h1><div class="card"><h2>Download SQL backup</h2><p>Backs up users, employees, and audit logs. Back up the uploads folder separately.</p><form method="post"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="backup"><button>Download backup (.sql)</button></form></div><div class="card"><h2>Restore</h2><p>Automatic restore is intentionally not enabled in this starter version. In phpMyAdmin, select hr_records and use Import with a trusted backup after taking a fresh backup. Restoring can overwrite data. Keep backups private and never commit them to GitHub.</p></div>';page_footer();